APPROVED=DATA["manifest"]
FILES=DATA["files"]
IMPORTER="Assets/AarisWorld/Editor/AarisTreeShapeImporter.cs"


def hashdata(value):
    return hashlib.sha256(value).hexdigest()


def gitblob(value):
    return hashlib.sha1(b"blob "+str(len(value)).encode()+b"\0"+value).hexdigest()


def execute():
    if not ORIGINAL.is_dir() or ORIGINAL.is_symlink() or not SCRATCH.is_dir() or SCRATCH.is_symlink():
        raise ValueError("Original or scratch Unity project missing/symlinked")
    if shutil.disk_usage(SCRATCH).free<5*1024**3:
        raise ValueError("Scratch disk insufficient for safe selective Unity reimport")
    profiles=APPROVED["profiles"]
    if APPROVED.get("schema_version")!=2 or len(profiles)!=6 or len(FILES)!=13:
        raise ValueError("Reviewed SpeedTree source manifest incomplete")
    expected={}
    for row in profiles:
        for typekey,blobkey in (("prefab","reviewed_prefab_git_blob_sha1"),
                                ("source_meta","reviewed_source_meta_git_blob_sha1")):
            expected[row[typekey]]=row[blobkey]
    if set(FILES)!=set(expected)|{IMPORTER}:
        raise ValueError("Unexpected file in approved Unity selective update")
    plan=[]
    already=[]
    for relative,value in FILES.items():
        p=PurePosixPath(relative)
        if not relative.startswith("Assets/") or p.is_absolute() or ".." in p.parts or "\\" in relative:
            raise ValueError("Unsafe tree source filename")
        data=value.encode("utf-8")
        if relative in expected and gitblob(data)!=expected[relative]:
            raise ValueError("Source hash differs from exact merged reviewed v2 prefab/metadata")
        if relative==IMPORTER and (b"GetVersion() { return 2; }" not in data or
                                   b'"aaris-tree-shape-v2"' not in data):
            raise ValueError("Approved Unity importer v2 is unavailable")
        original=ORIGINAL.joinpath(*p.parts)
        destination=SCRATCH.joinpath(*p.parts)
        if original.is_symlink() or destination.is_symlink() or not original.is_file() or not destination.is_file():
            raise ValueError("Original/scratch source missing or linked: "+relative)
        before=original.read_bytes()
        current=destination.read_bytes()
        if current==data:
            already.append(relative)
            continue
        if current!=before:
            raise ValueError("Scratch has concurrent tree modifications; refuse overwrite: "+relative)
        if relative.endswith(".st.meta"):
            old=re.search(rb"(?m)^guid: ([0-9a-f]{32})$",before)
            new=re.search(rb"(?m)^guid: ([0-9a-f]{32})$",data)
            if not old or not new or old.group(1)!=new.group(1):
                raise ValueError("SpeedTree GUID changed")
        plan.append((relative,destination,data,current))
    if already and plan:
        raise ValueError("Partially applied v2 sources; refuse unsupervised reapplication")
    if not plan:
        return {"status":"already_reviewed_tree_v2_in_scratch",
                "unity_source_files":len(FILES),"original_untouched":True}
    if BACKUP.exists() or BACKUP.is_symlink():
        raise ValueError("Prior tree-v2 scratch backup exists; manual review required")
    BACKUP.mkdir(mode=0o700)
    for relative,destination,data,current in plan:
        copy=BACKUP/relative
        copy.parent.mkdir(parents=True,exist_ok=True)
        copy.write_bytes(current)
    written=[]
    try:
        for relative,destination,data,current in plan:
            tmp=destination.with_name(destination.name+".aaris-tree-v2-new")
            if tmp.exists() or tmp.is_symlink():
                raise ValueError("Unexpected source temp file")
            with tmp.open("xb") as file:
                file.write(data)
                file.flush()
                os.fsync(file.fileno())
            os.replace(tmp,destination)
            written.append((relative,destination))
            if hashdata(destination.read_bytes())!=hashdata(data):
                raise ValueError("Failed scratch data readback")
    except BaseException:
        for relative,destination in reversed(written):
            os.replace(BACKUP/relative,destination)
